  &reftitle.description;

   stringsubstr
   stringstring
   intoffset
   intnulllength&null;


offset र length parameters द्वारा निर्दिष्ट गरिएको string को भाग return गर्दछ।

&reftitle.changelog;





    &Version;
    &Description;





    8.0.0
    length अब nullable भएको छ। जब length लाई स्पष्ट रूपमा &null; set गरिन्छ, तब यो function ले string को end मा समाप्त हुने substring return गर्दछ, जबकि पहिले यसले एउटा empty string return गर्दथ्यो।



    8.0.0
    यो function ले एउटा empty string return गर्दछ जहाँ पहिले यसले &false; return गर्दथ्यो।

  &reftitle.examples;



    substr को आधारभूत प्रयोग


<?php
echo substr('abcdef', 1), PHP_EOL;     // bcdef
echo substr("abcdef", 1, null), PHP_EOL; // bcdef; prior to PHP 8.0.0, empty string was returned
echo substr('abcdef', 1, 3), PHP_EOL;  // bcd
echo substr('abcdef', 0, 4), PHP_EOL;  // abcd
echo substr('abcdef', 0, 8), PHP_EOL;  // abcdef
echo substr('abcdef', -1, 1), PHP_EOL; // f

// Accessing single characters in a string
// can also be achieved using "square brackets"
$string = 'abcdef';
echo $string[0], PHP_EOL;                 // a
echo $string[3], PHP_EOL;                 // d
echo $string[strlen($string)-1], PHP_EOL; // f

?>




    substr को casting व्यवहार


<?php
class apple {
    public function __toString() {
        return "green";
    }
}

echo "1) ", var_export(substr("pear", 0, 2), true), PHP_EOL;
echo "2) ", var_export(substr(54321, 0, 2), true), PHP_EOL;
echo "3) ", var_export(substr(new apple(), 0, 2), true), PHP_EOL;
echo "4) ", var_export(substr(true, 0, 1), true), PHP_EOL;
echo "5) ", var_export(substr(false, 0, 1), true), PHP_EOL;
echo "6) ", var_export(substr("", 0, 1), true), PHP_EOL;
echo "7) ", var_export(substr(1.2e3, 0, 4), true), PHP_EOL;
?>


    &example.outputs;


1) 'pe'
2) '54'
3) 'gr'
4) '1'
5) ''
6) ''
7) '1200'




   अमान्य Character Range

यदि कुनै अमान्य character range अनुरोध गरियो भने, PHP 8.0.0 देखि substr ले एउटा empty string return गर्दछ; पहिले, यसको सट्टा &false; return गरिन्थ्यो।


<?php
var_dump(substr('a', 2));
?>


   &example.outputs.8;


string(0) ""


   &example.outputs.7;


bool(false)
